import{_ as e,o as t,c as a,a4 as p}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"河南邓州种植大户带领800多名农民数字化种植  大模型助力种小麦，出苗率提升近三成（春耕里的新质生产力）","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"河南邓州种植大户带领800多名农民数字化种植  大模型助力种小麦，出苗率提升近三成（春耕里的新质生产力）","date":"2026-06-04T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202605/t20260522_6484369.htm","summary":"南邓州种植大户带领800多名农民数字化种植\\n大模型助力种小麦,出苗率提升近三成(春耕里的新质生产力)\\n本报记者 毕京津《人民日报》(2026年04月30日 第 02 版)\\n晨雾还未散尽,泥土清香扑面而来。河南省邓州市文渠镇农户段傲笛蹲在田埂上,往年他需要把手伸进泥土里才能感受干湿,决定农机是否下田。但现在,他只要在手机上点开“慧耕耘”小程序,“土壤墒情21%、适宜机械耕作”等提示就能让他心里有底。...\\n","contentHash":"24fc4f5ed7916dd28b91d97e2dc8ed7b","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-06-04-河南邓州种植大户带领800多名农民数字化种植-大模型助力种小麦-出苗率提升近三成-春耕里的新质生产力.md","filePath":"news/2026-06-04-河南邓州种植大户带领800多名农民数字化种植-大模型助力种小麦-出苗率提升近三成-春耕里的新质生产力.md"}'),r={name:"news/2026-06-04-河南邓州种植大户带领800多名农民数字化种植-大模型助力种小麦-出苗率提升近三成-春耕里的新质生产力.md"};function n(s,_,o,d,l,c){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="河南邓州种植大户带领800多名农民数字化种植-大模型助力种小麦-出苗率提升近三成-春耕里的新质生产力" tabindex="-1">河南邓州种植大户带领800多名农民数字化种植 大模型助力种小麦，出苗率提升近三成（春耕里的新质生产力） <a class="header-anchor" href="#河南邓州种植大户带领800多名农民数字化种植-大模型助力种小麦-出苗率提升近三成-春耕里的新质生产力" aria-label="Permalink to &quot;河南邓州种植大户带领800多名农民数字化种植  大模型助力种小麦，出苗率提升近三成（春耕里的新质生产力）&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202605/t20260522_6484369.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-06-04 摘要: 南邓州种植大户带领800多名农民数字化种植 大模型助力种小麦,出苗率提升近三成(春耕里的新质生产力) 本报记者 毕京津《人民日报》(2026年04月30日 第 02 版) 晨雾还未散尽,泥土清香扑面而来。河南省邓州市文渠镇农户段傲笛蹲在田埂上,往年他需要把手伸进泥土里才能感受干湿,决定农机是否下田。但现在,他只要在手机上点开“慧耕耘”小程序,“土壤墒情21%、适宜机械耕作”等提示就能让他心里有底。...</p></blockquote><p>大模型助力种小麦,出苗率提升近三成(春耕里的新质生产力)</p><p>本报记者 毕京津《人民日报》(2026年04月30日 第 02 版)</p><p>晨雾还未散尽,泥土清香扑面而来。河南省邓州市文渠镇农户段傲笛蹲在田埂上,往年他需要把手伸进泥土里才能感受干湿,决定农机是否下田。但现在,他只要在手机上点开“慧耕耘”小程序,“土壤墒情21%、适宜机械耕作”等提示就能让他心里有底。</p><p>“农时耽误不起。往年得来回跑、反复摸土看墒情,现在看一眼手机就行。”段傲笛笑着说。</p><p>邓州春季多风少雨,土壤水分蒸发快,墒情关系苗情、收成。段傲笛种了20多年地,守着300多亩麦田,可每逢春天还是怕摸不准土地的“脾气”。</p><p>“抓起一把土,手握成团、落地变散,就算墒情合适。”段傲笛展示着祖辈传下来的土办法,“可这法子误差大,表层土湿、深层土干的情况时有发生。就算判断对了,也得看天气,万一浇完春水后下雨,地里多余水分容易闷坏麦苗子。”</p><p>同样感到困扰的种粮大户刘飞,在2024年秋收后联合南京农业大学和邓州市智慧农业中心,尝试攻克春耕墒情难题。农技部门负责本地气候、墒情数据采集与技术支撑,高校和科研机构团队负责模型算法研发,种粮大户对接农户需求。</p><p>段傲笛也加入了刘飞牵头的小麦种植合作社。不久后,“慧耕耘”大模型被开发出来,具备了土壤墒情精准监测、水肥一体化管控、数字化种植等功能。</p><p>“这几年见了不少高科技,有些是中看不中用,不适合咱们这地方。”段傲笛半信半疑。</p><p>刘飞和智慧农业中心工作人员热情邀请他现场观摩,讲解卫星遥感、无人机与地面传感器组成的监测网络,展示每5分钟更新的气象、墒情等数据,段傲笛下决心学习数字化种植。</p><p>而2025年春耕,用上新技术的段傲笛却开心不起来:“慧耕耘”提供的墒情数据时常有偏差,推送的农事建议与田间实际不符。</p><p>“还不如手摸得准。”段傲笛和几名农户抱怨。</p><p>刘飞找到智慧农业中心主任李占,采集地块样本后,发现“慧耕耘”使用的模型更适配南方土壤,对邓州的砂姜黑土“水土不服”。</p><p>白天段傲笛带着农技人员跑田块,晚上刘飞与南京农业大学专家线上沟通。反复优化模型参数,将传统测墒结果与传感器数据逐一对比,把砂姜黑土特性、气候规律、小麦生长习性录入系统。3个多月里,模型结合本地实际进行了校准,准确率提升至92%。</p><p>今年春耕,依托“慧耕耘”墒情监测,段傲笛的300多亩地实现水肥一体化管控,墒情低于18%自动预警,达标后立即停灌。春灌用水减少近两成,追肥用量节省超20%,每亩节约成本三四十元,小麦出苗率提升近三成。</p><p>“一年下来能多赚十来万元,数字化种植省力又高效。”段傲笛算起收益。</p><p>在智慧农业中心支持下,刘飞发起了“职业农民田间课堂”。农技专家与刘飞手把手教农户操作手机、解读数据,手机成了大家不离手的新农具。当地800多名农民学会数字化种植,“靠天收”的农田,变成了精准运转的“农业车间”。</p><p>对“慧耕耘”小程序,段傲笛仍有些期待,“希望模型进一步适配小农户零散地块,操作再简化些。”李占表示,“将推出小农户简易版功能,完善设备维护、数据解读配套服务。”</p><p>“打造这套系统,就是想让大数据解决实际问题,成为我们都用得起、用得好的新农技。”刘飞说。</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202605/t20260522_6484369.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',22)])])}const h=e(r,[["render",n]]);export{i as __pageData,h as default};
